// Tests of play-cap.sh: node --test .github/scripts/
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import test from 'node:test';
import { fileURLToPath } from 'node:url';

const script = path.join(path.dirname(fileURLToPath(import.meta.url)), 'play-cap.sh');

// A repository of its own: the script finds the repository from its own path, so it is copied in.
// files maps a name in backend/internal/play to its content ('' dirs are made as needed).
function run(cap, files, args = []) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'play-cap-'));
  fs.mkdirSync(path.join(dir, '.github', 'scripts'), { recursive: true });
  fs.copyFileSync(script, path.join(dir, '.github', 'scripts', 'play-cap.sh'));
  if (cap !== null) fs.writeFileSync(path.join(dir, '.github', 'play-cap'), `${cap}\n`);
  for (const [name, content] of Object.entries(files)) {
    const file = path.join(dir, 'backend', 'internal', 'play', name);
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, content);
  }
  const result = spawnSync('bash', [path.join(dir, '.github', 'scripts', 'play-cap.sh'), ...args], { cwd: dir, encoding: 'utf8' });
  const capAfter = cap === null ? null : fs.readFileSync(path.join(dir, '.github', 'play-cap'), 'utf8').trim();
  return { status: result.status, out: result.stdout + result.stderr, capAfter };
}

const four = 'package play\n\nfunc A() {}\nfunc B() {}\n'; // 4 lines, 2 functions
const files = { 'a.go': four, 'b.go': four }; // 8 lines

test('a count equal to the cap passes and prints the three numbers', () => {
  const r = run(8, files);
  assert.equal(r.status, 0);
  assert.match(r.out, /8 lines in 2 files, 4 functions \(cap 8 lines\)/);
});

test('a count over the cap fails and names the cap file', () => {
  const r = run(7, files);
  assert.equal(r.status, 1);
  assert.match(r.out, /file=\.github\/play-cap/);
});

test('a count under the cap passes with a notice, and leaves the file alone', () => {
  const r = run(9, files);
  assert.equal(r.status, 0);
  assert.match(r.out, /::notice/);
  assert.equal(r.capAfter, '9');
});

test('--lower writes the cap down to the count', () => {
  const r = run(20, files, ['--lower']);
  assert.equal(r.status, 0);
  assert.equal(r.capAfter, '8');
});

test('--lower never raises the cap', () => {
  const r = run(5, files, ['--lower']);
  assert.equal(r.status, 1);
  assert.equal(r.capAfter, '5');
});

test('test files, generated files and subpackages count for nothing', () => {
  const r = run(8, {
    ...files,
    'a_test.go': four,
    'gen.go': '// Code generated by x. DO NOT EDIT.\npackage play\n',
    'testdata/x.go': four,
    'advantage/a.go': four,
  });
  assert.equal(r.status, 0);
  assert.match(r.out, /8 lines in 2 files/);
});

test('a missing or malformed cap file is an error, not a pass', () => {
  assert.equal(run(null, files).status, 2);
  assert.equal(run('lots', files).status, 2);
});

test('no Go file in the package is an error, not a pass', () => {
  assert.equal(run(8, { 'a_test.go': four }).status, 2);
});

test('an unknown argument is a usage error', () => assert.equal(run(8, files, ['--raise']).status, 2));
